import {readdir,writeFile} from 'node:fs/promises';
import {join,relative,sep} from 'node:path';

// Create a complete allowlist of the static files generated by Vite.
// The browser installer fetches and uploads only these exact files.
const root='dist';
async function visit(folder){
 const items=await readdir(folder,{withFileTypes:true});
 const paths=[];
 for(const item of items){
  if(item.name.startsWith('.'))continue;
  const path=join(folder,item.name);
  if(item.isDirectory())paths.push(...await visit(path));
  else if(item.isFile()&&item.name!=='group-install-manifest.json'){
   paths.push('/'+relative(root,path).split(sep).join('/'));
  }
 }
 return paths;
}
const files=(await visit(root)).sort();
if(!files.includes('/index.html'))throw Error('Vite did not produce an index.html for the installer.');
await writeFile(join(root,'group-install-manifest.json'),JSON.stringify({
 kind:'volleyball-night-install-manifest',version:1,files
},null,2)+'\n');
process.stdout.write('Group installer manifest includes '+files.length+' static files.\n');
